el</a><a href="showdoctor.php">Doktorlar</a><a href="showclinic.php">Klinikler</a><a class="active" href="showmanager.php">Managerlar</a></nav></header><main class="admin-wrap"><div class="page-head"><div><span class="admin-eyebrow">MANAGER YÖNETİMİ</span><h1>Managerlar</h1><p>Sistemde kayıtlı manager hesaplarının güncel listesini görüntüleyin.</p></div><a class="admin-button" href="addmanager.php">+ Manager Ekle</a></div><section class="admin-card table-card"><div class="table-top"><h2>Manager listesi</h2><span class="count"><?php echo $count;?> manager</span></div><?php if(!$count):?><div class="empty">Kayıtlı manager bulunmuyor.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>MID</th><th>Manager</th><th>Doğum</th><th>Adres</th><th>İletişim</th><th>Bölge</th></tr></thead><tbody><?php while($r=$result->fetch_assoc()):?><tr><td>#<?php echo (int)$r['MID'];?></td><td class="manager-name"><?php echo htmlspecialchars($r['Name']);?></td><td><?php echo htmlspecialchars($r['DOB']);?></td><td class="muted"><?php echo htmlspecialchars($r['Address']);?></td><td><?php echo htmlspecialchars($r['Contact']);?></td><td><?php echo htmlspecialchars($r['Region']);?></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></section></main></body></html>